var products=[
 {code:'779001',name:'Alfajor chocolate',cat:'Golosinas',price:85000,cost:50000,stock:36,pack:12,min:8,art:'chocolate',photo:''},
 {code:'779002',name:'Detergente 750 ml',cat:'Limpieza',price:190000,cost:120000,stock:18,pack:6,min:6,art:'cleaning',photo:''},
 {code:'779003',name:'Cigarrillos x20',cat:'Cigarrillos',price:420000,cost:350000,stock:7,pack:10,min:8,art:'cigarettes',photo:''},
 {code:'779004',name:'Agua mineral 500 ml',cat:'Productos varios',price:120000,cost:70000,stock:24,pack:6,min:6,art:'water',photo:''}
];
var cfg={shop:'Mi comercio',legal:'Razón social de ejemplo',box:'Caja 01',user:'Cajero de prueba',role:'Administrador',mode:'Principal',host:'192.168.1.10',paper:'80 mm',display:false,walletView:'both',alias:'',wallet:'Mercado Pago',holder:'',qr:'',qrPDF:false,logo:'',scanSound:false,cashSound:false};
var cart=[],sales=[],closures=[],opened=true,opening=1000000,withdrawals=0;
var customer=null,customerState='cart',lastSale=null,toastTimer=null,customerTimer=null,editIndex=-1;
var methods=['Efectivo','Wallet / transferencia','Débito','Crédito'];
function E(id){return document.getElementById(id)}
function esc(v){return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
function trim(v){return String(v).replace(/^\s+|\s+$/g,'')}
function money(v){return '$ '+(v/100).toFixed(2).replace('.',',')}
function inputMoney(v){return (v/100).toFixed(2)}
function fileURL(path){return 'file:///'+path.replace(/\\/g,'/').replace(/%/g,'%25').replace(/#/g,'%23').replace(/\?/g,'%3F').replace(/ /g,'%20')}
function toast(t){E('toast').innerText=t;E('toast').className='';clearTimeout(toastTimer);toastTimer=setTimeout(function(){E('toast').className='hidden'},4500)}
function art(p){var fallback='assets/'+p.art+'.svg';return '<img class="photo" src="'+esc(p.photo||fallback)+'"'+(p.photo?' onerror="this.onerror=null;this.src=\''+fallback+'\'"':'')+'>'}
function options(a,v){var h='';for(var i=0;i<a.length;i++)h+='<option value="'+esc(a[i])+'"'+(a[i]===v?' selected':'')+'>'+esc(a[i])+'</option>';return h}
function modal(title,body,buttons){E('modalTitle').innerText=title;E('modalBody').innerHTML=body;E('modalActions').innerHTML=buttons||'<button onclick="closeModal()">Cerrar</button>';E('overlay').className=''}
function closeModal(){E('overlay').className='hidden';if(customerState==='wallet'){customerState='cart';updateCustomer()}}
function tab(id){var a=['caja','arqueo','insumos'];for(var i=0;i<a.length;i++){E(a[i]).className=a[i]===id?'':'hidden';E('nav_'+a[i]).className=a[i]===id?'active':''}render();if(id==='caja')E('scan').focus()}
function total(){return PosCore.total(cart,products)}
function render(){E('identity').innerText=cfg.box+' · '+cfg.user+' · '+cfg.role;E('network').innerText=cfg.mode+' · Red simulada';E('saleState').innerText=opened?'Turno abierto':'Turno cerrado';E('shop').innerText=cfg.shop;renderCart();renderProducts();renderAudit();updateCustomer()}
function renderCart(){var h='',q=0;for(var i=0;i<cart.length;i++){var c=cart[i],p=products[c.p];q+=c.q;h+='<tr><td>'+art(p)+'<b>'+esc(p.name)+'</b><br><small>'+esc(p.code)+'</small></td><td><button onclick="qty('+i+',-1)">−</button> '+c.q+' <button onclick="qty('+i+',1)">+</button></td><td class="num">'+money(p.price*c.q)+'</td><td><button class="danger" onclick="removeItem('+i+')">×</button></td></tr>'}E('cartRows').innerHTML=h||'<tr><td colspan="4" class="empty">Escaneá un producto para comenzar</td></tr>';E('total').innerText=money(total());E('units').innerText=q+' unidades'}
function add(i){if(!opened){toast('Abrí un turno desde Arqueo');return}var k=-1;for(var j=0;j<cart.length;j++)if(cart[j].p===i)k=j;var q=k<0?0:cart[k].q;if(q>=products[i].stock){toast('Stock insuficiente');return}if(k<0)cart.push({p:i,q:1});else cart[k].q++;customerState='cart';clearTimeout(customerTimer);renderCart();updateCustomer();E('scan').value='';E('scan').focus();playSound('scan')}
function scan(){var code=trim(E('scan').value);if(!code)return;for(var i=0;i<products.length;i++)if(products[i].code===code){add(i);return}productForm(-1,code);toast('Código nuevo: completá el producto')}
function qty(i,n){if(cart[i].q+n<=0){removeItem(i);return}if(cart[i].q+n>products[cart[i].p].stock){toast('Stock insuficiente');return}cart[i].q+=n;renderCart();updateCustomer()}
function removeItem(i){cart.splice(i,1);renderCart();updateCustomer()}
function clearCart(){if(cart.length&&confirm('¿Vaciar la venta?')){cart=[];renderCart();updateCustomer()}}
function pay(){if(!opened||!cart.length){toast('Agregá productos en un turno abierto');return}customerState='cart';var labels=['Efectivo recibido','Wallet / transferencia','Débito','Crédito'];var h='<p class="muted">Distribuí el total entre los medios de pago.</p><div class="total">'+money(total())+'</div>';for(var i=0;i<4;i++)h+='<label>'+labels[i]+'</label><input id="pay'+i+'" type="number" min="0" step="0.01" value="'+(i===0?inputMoney(total()):'0')+'" oninput="paymentChanged()" onchange="paymentChanged()">';h+='<button class="full" onclick="walletCustomer()">Cobrar por wallet / mostrar importe</button><div class="checkline"><input id="verified" type="checkbox" style="width:auto"> Verifiqué la acreditación wallet en la cuenta del comercio.</div><p class="muted">El QR y el alias no verifican pagos automáticamente.</p>';modal('Cobrar venta',h,'<button onclick="closeModal()">Volver</button><button class="primary" onclick="confirmSale()">Confirmar cobro</button>');updateCustomer()}
function paymentChanged(){if(E('verified'))E('verified').checked=false;var n=E('pay1')?Number(E('pay1').value):0;customerState=isFinite(n)&&n>0?'wallet':'cart';updateCustomer()}
function walletReady(){if(cfg.walletView==='qr')return !!cfg.qr;if(cfg.walletView==='alias')return !!trim(cfg.alias);return !!cfg.qr&&!!trim(cfg.alias)}
function walletCustomer(){if(!cfg.display){toast('Habilitá la pantalla del cliente desde Ajustes');return}if(!walletReady()){toast('Completá QR / alias en Ajustes');return}var n=Number(E('pay1').value);if(!isFinite(n)||n<=0){E('pay0').value='0';E('pay1').value=inputMoney(total());E('pay2').value='0';E('pay3').value='0'}E('verified').checked=false;customerState='wallet';openCustomer()}
function confirmSale(){if(!opened){toast('El turno está cerrado');return}try{var a=[];for(var i=0;i<4;i++)a.push(PosCore.amount(E('pay'+i).value));var sale=PosCore.prepare(cart,products,a,E('verified').checked);var low=[];for(var j=0;j<cart.length;j++){var c=cart[j],p=products[c.p];p.stock-=c.q;if(p.stock<=p.min)low.push(p.name)}sale.id=sales.length+1;sale.date=new Date().toLocaleString();sale.box=cfg.box;sale.user=cfg.user;sale.closed=false;lastSale=sale;sales.push(sale);cart=[];customerState='result';closeModal();render();playSound('cash');toast(low.length?'Reposición: '+low.join(', '):'Venta confirmada');clearTimeout(customerTimer);customerTimer=setTimeout(function(){customerState='idle';updateCustomer()},12000)}catch(e){toast(e.message)}}
function ticket(){if(!lastSale){toast('No hay ventas');return}var s=lastSale,t=cfg.shop+'\n'+cfg.legal+'\nTICKET INTERNO · NO FISCAL\n------------------------------\nVenta '+s.id+' · '+s.date+'\n'+s.box+' · '+s.user+'\n';for(var i=0;i<s.lines.length;i++)t+='\n'+s.lines[i].q+' × '+s.lines[i].name+'\n'+money(s.lines[i].price*s.lines[i].q);t+='\n------------------------------\nTOTAL '+money(s.total)+'\n';for(var j=0;j<4;j++)if(s.payments[j])t+='\n'+methods[j]+': '+money(s.payments[j]);if(s.received>0)t+='\nEfectivo recibido: '+money(s.received)+'\nVuelto: '+money(s.change);else if(s.payments[1]===s.total)t+='\nCobrado OK';t+='\n\n¡Gracias por tu compra!';modal('Ticket · '+cfg.paper,'<p class="muted">Vista previa. Sin impresión térmica en esta beta.</p>'+(cfg.logo?'<img src="'+esc(cfg.logo)+'" style="max-width:150px;max-height:80px">':'')+'<div class="receipt">'+esc(t)+'</div>')}
function renderProducts(){var query=E('search').value.toLowerCase(),cat=E('filter').value,h='';for(var i=0;i<products.length;i++){var p=products[i];if((p.name+' '+p.code).toLowerCase().indexOf(query)<0||(cat&&cat!==p.cat))continue;h+='<tr><td>'+art(p)+'<b>'+esc(p.name)+'</b><br><small>'+esc(p.code)+'</small></td><td>'+esc(p.cat)+'</td><td>'+money(p.price)+'</td><td><b class="'+(p.stock<=p.min?'warning':'')+'">'+p.stock+' unidades</b><br><small>'+Math.floor(p.stock/p.pack)+' bultos + '+p.stock%p.pack+' u. · x'+p.pack+'</small></td><td><button onclick="productForm('+i+')">Editar</button> <button onclick="receive('+i+')">+ Stock</button></td></tr>'}E('productRows').innerHTML=h||'<tr><td colspan="5">Sin resultados</td></tr>'}
function productForm(i,code){if(cart.length){toast('Terminá o vaciá la venta antes de editar productos');return}editIndex=i;var p=i<0?{code:code||'',name:'',cat:'Productos varios',price:0,cost:0,stock:0,pack:1,min:5,art:'box',photo:''}:products[i];modal(i<0?'Nuevo producto':'Editar producto','<label>Código de barras</label><input id="pcode" value="'+esc(p.code)+'"><label>Nombre</label><input id="pname" value="'+esc(p.name)+'"><label>Categoría</label><select id="pcat">'+options(['Limpieza','Cigarrillos','Golosinas','Productos varios'],p.cat)+'</select><label>Costo unitario</label><input id="pcost" type="number" step="0.01" value="'+inputMoney(p.cost)+'"><label>Precio de venta</label><input id="pprice" type="number" step="0.01" value="'+inputMoney(p.price)+'"><label>Stock en unidades</label><input id="pstock" type="number" value="'+p.stock+'"><label>Unidades por bulto</label><input id="ppack" type="number" value="'+p.pack+'"><label>Alerta al llegar a</label><input id="pmin" type="number" value="'+p.min+'"><label>Ilustración</label><select id="part">'+options(['box','chocolate','cleaning','cigarettes','water'],p.art)+'</select><label>Foto propia JPG / PNG</label><input id="pphoto" type="file" accept=".jpg,.jpeg,.png"><p class="muted">Sin archivo nuevo se conserva la foto. La búsqueda por Internet está pendiente.</p>','<button onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveProduct()">Guardar</button>')}
function saveProduct(){try{var code=trim(E('pcode').value),name=trim(E('pname').value),price=PosCore.amount(E('pprice').value),cost=PosCore.amount(E('pcost').value);var stock=Number(E('pstock').value),pack=Number(E('ppack').value),min=Number(E('pmin').value);if(!code||!name||trim(E('pstock').value)===''||trim(E('ppack').value)===''||trim(E('pmin').value)===''||!isFinite(stock)||stock<0||stock%1||!isFinite(pack)||pack<1||pack%1||!isFinite(min)||min<0||min%1)throw Error('Revisá los datos');for(var i=0;i<products.length;i++)if(i!==editIndex&&products[i].code===code)throw Error('Código duplicado');var photo=editIndex<0?'':products[editIndex].photo;if(E('pphoto').value){if(!/\.(png|jpe?g)$/i.test(E('pphoto').value))throw Error('Elegí JPG o PNG');photo=fileURL(E('pphoto').value)}var p={code:code,name:name,cat:E('pcat').value,price:price,cost:cost,stock:stock,pack:pack,min:min,art:E('part').value,photo:photo};if(editIndex<0)products.push(p);else products[editIndex]=p;closeModal();render();toast('Producto guardado en esta sesión')}catch(e){toast(e.message)}}
function receive(i){var raw=prompt('Bultos completos a ingresar:',1);if(raw===null)return;var n=Number(raw);if(!isFinite(n)||n<=0||n%1){toast('Ingresá un entero positivo');return}products[i].stock+=n*products[i].pack;render();toast('Stock actualizado')}
function paymentTotals(){var a=[0,0,0,0];for(var i=0;i<sales.length;i++)if(!sales[i].closed)for(var j=0;j<4;j++)a[j]+=sales[i].payments[j];return a}
function renderAudit(){var a=paymentTotals(),h='';for(var i=0;i<4;i++)h+='<tr><td>'+methods[i]+'</td><td class="num">'+money(a[i])+'</td></tr>';E('auditRows').innerHTML=h;E('expected').innerText=money(opening+a[0]-withdrawals);E('openAmount').innerText=money(opening);E('outAmount').innerText=money(withdrawals);E('turnLabel').innerText=(opened?'Turno activo':'Turno cerrado')+' · '+cfg.box+' · '+cfg.user;var c='';for(var j=0;j<closures.length;j++){var x=closures[j];c+='<tr><td>'+esc(x.date)+'</td><td>'+esc(x.box)+'</td><td>'+esc(x.user)+'</td><td>'+money(x.difference)+'</td><td><button onclick="viewClosure('+j+')">Detalle</button></td></tr>'}E('closureRows').innerHTML=c||'<tr><td colspan="5">Todavía no hay cierres.</td></tr>'}
function withdraw(){if(!opened){toast('El turno está cerrado');return}var raw=prompt('Importe del retiro de efectivo:',0);if(raw===null)return;try{var n=PosCore.amount(raw);if(n<=0||n>opening+paymentTotals()[0]-withdrawals)throw Error('Importe inválido');withdrawals+=n;renderAudit()}catch(e){toast(e.message)}}
function closeTurn(){if(!opened){toast('El turno está cerrado');return}if(cart.length){toast('Finalizá o vaciá la venta pendiente');return}var a=paymentTotals(),h='<p class="muted">Declaraciones por medio. Lotes bancarios de tarjetas pendientes.</p>';for(var i=0;i<4;i++)h+='<label>'+methods[i]+' · esperado '+money(i===0?opening+a[0]-withdrawals:a[i])+'</label><input id="count'+i+'" type="number" min="0" step="0.01" value="0">';modal('Arqueo y cierre de turno',h,'<button onclick="closeModal()">Volver</button><button class="primary" onclick="finishTurn()">Confirmar cierre</button>')}
function finishTurn(){try{var a=paymentTotals(),diff=0,details=[];for(var i=0;i<4;i++){var n=PosCore.amount(E('count'+i).value),expected=i===0?opening+a[0]-withdrawals:a[i],d=n-expected;diff+=d;details.push({expected:expected,declared:n,difference:d})}closures.push({date:new Date().toLocaleString(),box:cfg.box,user:cfg.user,difference:diff,details:details});for(var j=0;j<sales.length;j++)sales[j].closed=true;opened=false;opening=0;withdrawals=0;render();viewClosure(closures.length-1)}catch(e){toast(e.message)}}
function viewClosure(i){var c=closures[i],h='<p>'+esc(c.date)+' · '+esc(c.box)+' · '+esc(c.user)+'</p><table class="data"><tr><th>Medio</th><th>Esperado</th><th>Declarado</th><th>Diferencia</th></tr>';for(var j=0;j<4;j++){var d=c.details[j];h+='<tr><td>'+methods[j]+'</td><td>'+money(d.expected)+'</td><td>'+money(d.declared)+'</td><td>'+money(d.difference)+'</td></tr>'}modal('Detalle del cierre',h+'</table>')}
function openTurn(){if(opened){toast('Ya hay un turno abierto');return}var raw=prompt('Saldo inicial en efectivo:',0);if(raw===null)return;try{opening=PosCore.amount(raw);opened=true;render();toast('Nuevo turno abierto')}catch(e){toast(e.message)}}
function switchButton(id,value){return '<button id="'+id+'" class="switch '+(value?'on':'')+'" data-on="'+(value?'1':'0')+'" onclick="toggle(\''+id+'\')">'+(value?'Activado':'Desactivado')+'</button>'}
function toggle(id){var e=E(id),value=e.getAttribute('data-on')!=='1';e.setAttribute('data-on',value?'1':'0');e.className='switch '+(value?'on':'');e.innerText=value?'Activado':'Desactivado'}
function on(id){return E(id).getAttribute('data-on')==='1'}
function config(){modal('Ajustes','<h3 class="sectiontitle">Comercio y ticket</h3><label>Nombre comercial</label><input id="sShop" value="'+esc(cfg.shop)+'"><label>Razón social</label><input id="sLegal" value="'+esc(cfg.legal)+'"><label>Logo JPG / PNG</label><input id="sLogo" type="file" accept=".jpg,.jpeg,.png"><label>Papel térmico</label><select id="sPaper">'+options(['58 mm','80 mm'],cfg.paper)+'</select><h3 class="sectiontitle">Caja y sesión</h3><label>Nombre de caja</label><input id="sBox" value="'+esc(cfg.box)+'"><label>Cajero</label><input id="sUser" value="'+esc(cfg.user)+'"><label>Perfil simulado</label><select id="sRole">'+options(['Administrador','Supervisor','Cajero'],cfg.role)+'</select><label>Modo de equipo</label><select id="sMode">'+options(['Principal','Secundaria','Independiente'],cfg.mode)+'</select><label>Dirección de la principal</label><input id="sHost" value="'+esc(cfg.host)+'"><p class="muted">Cerrá el turno antes de cambiar caja o cajero. Red y permisos simulados.</p><h3 class="sectiontitle">Pantalla del cliente</h3><div class="checkline">Habilitar ventana secundaria '+switchButton('sDisplay',cfg.display)+'</div><label>Opciones de pago visibles</label><select id="sView"><option value="qr">Solo QR</option><option value="alias">Solo alias</option><option value="both">QR y alias</option></select><label>Archivo QR JPG / JPEG / PNG / PDF</label><input id="sQR" type="file" accept=".jpg,.jpeg,.png,.pdf"><p class="muted">'+(cfg.qr?'Hay un QR cargado. Sin archivo nuevo se conserva.':'Todavía no hay QR.')+' PDF depende del visor instalado. Recomendado PNG/JPG.</p><label>Alias</label><input id="sAlias" value="'+esc(cfg.alias)+'"><label>Wallet / banco</label><input id="sWallet" value="'+esc(cfg.wallet)+'"><label>Titular</label><input id="sHolder" value="'+esc(cfg.holder)+'"><h3 class="sectiontitle">Sonidos</h3><div class="checkline">Bip al agregar producto '+switchButton('sScan',cfg.scanSound)+'</div><button onclick="playSound(\'scan\',true)">Probar bip</button><div class="checkline">Caja registradora al cobrar '+switchButton('sCash',cfg.cashSound)+'</div><button onclick="playSound(\'cash\',true)">Probar caja registradora</button>','<button onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveConfig()">Guardar ajustes</button>');E('sView').value=cfg.walletView}
function saveConfig(){var box=trim(E('sBox').value),user=trim(E('sUser').value),shop=trim(E('sShop').value);if(!box||!user||!shop){toast('Completá comercio, caja y cajero');return}if(opened&&(box!==cfg.box||user!==cfg.user)){toast('Cerrá el turno antes de cambiar caja o cajero');return}var qr=cfg.qr,pdf=cfg.qrPDF,path=E('sQR').value,view=E('sView').value,alias=trim(E('sAlias').value);if(path){if(!/\.(png|jpe?g|pdf)$/i.test(path)){toast('QR: elegí PNG, JPG o PDF');return}qr=fileURL(path);pdf=/\.pdf$/i.test(path)}if(on('sDisplay')&&((view==='qr'&&!qr)||(view==='alias'&&!alias)||(view==='both'&&(!qr||!alias)))){toast('Completá QR, alias o ambos según la opción elegida');return}var logo=cfg.logo;if(E('sLogo').value){if(!/\.(png|jpe?g)$/i.test(E('sLogo').value)){toast('Logo: elegí JPG o PNG');return}logo=fileURL(E('sLogo').value)}cfg.shop=shop;cfg.legal=E('sLegal').value;cfg.box=box;cfg.user=user;cfg.role=E('sRole').value;cfg.mode=E('sMode').value;cfg.host=E('sHost').value;cfg.paper=E('sPaper').value;cfg.logo=logo;cfg.display=on('sDisplay');cfg.walletView=view;cfg.alias=alias;cfg.wallet=trim(E('sWallet').value);cfg.holder=trim(E('sHolder').value);cfg.qr=qr;cfg.qrPDF=pdf;cfg.scanSound=on('sScan');cfg.cashSound=on('sCash');closeModal();render();if(cfg.display)openCustomer();else try{if(customer&&!customer.closed)customer.close()}catch(e){}toast('Ajustes aplicados a esta sesión')}
function openCustomer(){if(!cfg.display){toast('Activá la pantalla del cliente en Ajustes');return}try{if(!customer||customer.closed){customer=window.open('','PoStoreBairesCliente','width=950,height=800,resizable=yes,scrollbars=yes');if(!customer){toast('No se pudo abrir la ventana secundaria');return}customer.document.open();customer.document.write('<!DOCTYPE html><html><head><meta charset="utf-8"><title>PoStoreBaires · Cliente</title><style>*{box-sizing:border-box}body{margin:0;background:#eef3fb;color:#24324a;font:20px Segoe UI,Arial;text-align:center}.card{margin:22px auto;padding:28px;background:white;border-radius:18px;max-width:1100px}h1{color:#2859ba;font-size:34px}h2{font-size:26px}.amount{font-size:55px;font-weight:bold;color:#2859ba;margin:14px 0}.alias{font-size:32px;font-weight:bold;word-wrap:break-word;color:#2859ba}.qr{width:280px;max-width:100%;height:auto}.muted{font-size:16px;color:#7b879c;line-height:1.6}table{width:100%;text-align:left;border-collapse:collapse}td{padding:10px;border-bottom:1px solid #eee}.ok{color:#16834d;font-size:40px}.logo{max-width:180px;max-height:85px}.cols{display:table;width:100%;table-layout:fixed}.col{display:table-cell;vertical-align:top;padding:10px 20px}.cartcol{width:45%;border-right:1px solid #e7edf5}.walletcol{width:55%}@media(max-width:750px){.cols,.col{display:block;width:100%}.cartcol{border:0}}</style></head><body><div id="content"></div></body></html>');customer.document.close()}updateCustomer();customer.focus()}catch(e){toast('No se pudo abrir la pantalla del cliente')}}
function customerWalletBlock(amount){var h='<h2>Pagá desde tu celular</h2><p>'+esc(cfg.wallet||'Wallet / transferencia')+'</p>';if(amount>0)h+='<p class="muted">IMPORTE A PAGAR</p><div class="amount">'+money(amount)+'</div>';if(cfg.walletView!=='alias'&&cfg.qr){if(cfg.qrPDF)h+='<object data="'+esc(cfg.qr)+'" type="application/pdf" width="100%" height="380"><p class="muted">No se pudo mostrar el PDF. Cargá PNG o JPG.</p></object>';else h+='<div style="background:white;padding:16px"><img class="qr" alt="QR para pagar" src="'+esc(cfg.qr)+'"></div>'}if(cfg.walletView!=='qr'&&cfg.alias)h+='<p class="muted">ALIAS PARA TRANSFERIR</p><div class="alias">'+esc(cfg.alias)+'</div>';if(cfg.holder)h+='<p>Titular: <b>'+esc(cfg.holder)+'</b></p>';h+='<p class="muted">'+(walletReady()?'Escaneá el QR o ingresá el alias en tu app.<br>Comprobá titular e importe antes de pagar.<br>Avisale al cajero cuando hayas terminado.':'El comercio debe completar los datos de pago en Ajustes.')+'</p>';return h}
function updateCustomer(){if(!cfg.display||!customer||customer.closed)return;try{var h='<div class="card">'+(cfg.logo?'<img class="logo" src="'+esc(cfg.logo)+'">':'')+'<h1>'+esc(cfg.shop)+'</h1>';if(customerState==='result'&&lastSale){var s=lastSale;h+='<div class="ok">'+(s.payments[1]===s.total?'Cobrado OK':'Venta confirmada')+'</div><div class="amount">'+money(s.total)+'</div>';for(var i=0;i<4;i++)if(s.payments[i]>0)h+='<p>'+methods[i]+': '+money(s.payments[i])+'</p>';if(s.received>0)h+='<h2>Tu vuelto: '+money(s.change)+'</h2>';h+='<p>¡Gracias por tu compra!</p>'}else{var amount=total();if(customerState==='wallet'&&E('pay1')){try{var n=PosCore.amount(E('pay1').value);if(n>0)amount=n}catch(e){}}if(cart.length){h+='<div class="cols"><div class="col cartcol"><h2>Tu compra</h2><table>';for(var j=0;j<cart.length;j++){var c=cart[j],p=products[c.p];h+='<tr><td>'+c.q+' × '+esc(p.name)+'</td><td style="text-align:right">'+money(p.price*c.q)+'</td></tr>'}h+='</table><p class="muted">TOTAL DE LA COMPRA</p><div class="amount">'+money(total())+'</div></div><div class="col walletcol">'+customerWalletBlock(amount)+'</div></div>'}else h+='<h2>¡Gracias por tu visita!</h2><p class="muted">Tu compra aparecerá aquí.</p>'+customerWalletBlock(0)}customer.document.getElementById('content').innerHTML=h+'</div>'}catch(e){}}
function playSound(kind,force){if(!force&&!(kind==='scan'?cfg.scanSound:cfg.cashSound))return;E('sound').src='';E('sound').src='assets/'+kind+'.wav'}
function help(){modal('Guía de configuración y uso','<div class="help"><h3>Inicio</h3><p>Turno de ejemplo: $10.000 iniciales. Códigos 779001–779004. El lector debe emular teclado con Enter.</p><h3>Cajas, perfiles y cajeros</h3><p>Cerrá el turno antes de cambiar caja o cajero en Ajustes. Abrí otro turno con saldo inicial. Los perfiles y la dirección de servidor son ilustrativos; no conectan equipos ni aplican permisos.</p><h3>Productos e imágenes</h3><p>En Insumos configurá costo, precio, stock mínimo y unidades por bulto. Tres bultos de doce suman 36 unidades. Elegí una ilustración o foto local. No hay búsqueda por Internet. No se editan productos con una venta pendiente.</p><h3>Tickets</h3><p>Configurá comercio, razón social, logo y papel 58/80 mm. Último ticket es una vista previa no fiscal, sin impresión.</p><h3>QR, alias y segundo monitor</h3><p>Activá la pantalla del cliente en Ajustes. Elegí Solo QR, Solo alias o ambos y completá los datos. Cargá PNG/JPG preferentemente; PDF requiere visor instalado y no se convierte. Mové la ventana al segundo monitor y maximizala. El QR/alias queda visible durante la compra.</p><h3>Pago desde el celular</h3><p>El cliente escanea el QR o ingresa el alias en su app, verifica titular e importe y paga. Un alias es texto, no un código escaneable. El QR estático puede requerir que ingrese el importe en su app.</p><h3>Cobro y pagos mixtos</h3><p>El primer campo es efectivo recibido. Distribuí los medios o presioná Cobrar por wallet para asignar todo a wallet. El importe wallet aparece en pantalla. Verificá la acreditación en la cuenta del comercio y marcá la casilla antes de confirmar. Editar importes desmarca la verificación. No hay validación automática ni integración de cobro.</p><h3>Resultado</h3><p>Se muestran total y medios. Efectivo muestra vuelto; wallet íntegra muestra Cobrado OK solo después de confirmar. A los 12 segundos vuelve la bienvenida con QR/alias.</p><h3>Arqueo</h3><p>Registrá retiros y declarados por medio al cerrar. El esperado de efectivo incluye saldo inicial, cobros y retiros. Consultá cada diferencia en Detalle. Los lotes bancarios de tarjetas serán registros separados.</p><h3>Sonidos</h3><p>Activá bip y caja registradora por separado en Ajustes. Los botones Probar funcionan antes de guardar.</p><h3>Datos temporales</h3><p>Todo se pierde al cerrar. No muevas imágenes/QR seleccionados durante la prueba. No uses datos ni ventas reales. Más información en docs/GUIA.md del paquete.</p></div>')}
window.onload=function(){render();E('scan').focus();toast('PoStoreBaires Beta 1.0 · Datos temporales. Consultá Ayuda.')};
window.onunload=function(){try{if(customer&&!customer.closed)customer.close()}catch(e){}};
document.onkeydown=function(e){e=e||window.event;if(e.keyCode===27)closeModal()};
